/* Signature Awadhi Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ramsita": "From Ram + Sita.", "Mohangita": "From Mohan + Gita: 'enchanting song'.", "Sitadevi": "From Sita + Devi.", "Ramkishore": "From Ram + Kishore.", "Gitamohan": "From Gita + Mohan.", "Devimohan": "From Devi + Mohan.", "Ramsitapuri": "Signature surname: 'of Ram-Sita city'.", "Mohangitadas": "Signature surname: 'servant of the enchanting song'.", "Sitadevipal": "Signature surname.", "Kishoreraman": "Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ramsita';
console.log(lookup(q));

